package com.bombay.restaurantintelligence.web;
import com.bombay.restaurantintelligence.whatsapp.*; import org.junit.jupiter.api.Test; import org.springframework.http.HttpStatus; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class WhatsAppWebhookControllerTest {@Test void verifiesCorrectToken(){var service=mock(WhatsAppWebhookService.class);var sig=mock(WhatsAppSignatureVerifier.class);var c=new WhatsAppWebhookController("verify-me",service,sig);var r=c.verify("subscribe","verify-me","challenge-123");assertThat(r.getStatusCode()).isEqualTo(HttpStatus.OK);assertThat(r.getBody()).isEqualTo("challenge-123");}@Test void rejectsWrongToken(){var c=new WhatsAppWebhookController("verify-me",mock(WhatsAppWebhookService.class),mock(WhatsAppSignatureVerifier.class));assertThat(c.verify("subscribe","wrong","x").getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);}}
